 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 classes.append(ast.dump(cls,include_attributes=False))
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 assert 'training_loss' not in methods and 'make_optimizer' not in [getattr(n,'name','') for n in tree.body]
 inherited=set(old_methods)-{'__init__','_identity_tables','diagnostics'}
 for name in inherited: assert ast.dump(methods[name])==ast.dump(old_methods[name]),name
 # Initializer only adds switch validation before the original allocations.
