  or isinstance(n,ast.If) and any(isinstance(a,ast.Attribute) and a.attr in ('summary_layout','constant_arithmetic') for a in ast.walk(n.test))
  or isinstance(n,ast.If) and ast.unparse(n.test)==\"self.summary_mode "'!= '"'local'\"
 )]
 assert ast.dump(new_init)==ast.dump(old_methods['__init__'])
 result_dict=next(n.value for n in ast.walk(methods['diagnostics']) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='result' for t in n.targets))
 assert len(result_dict.keys)<=64
 print(v['file'],'sha256',hashlib.sha256(source.encode()).hexdigest(),'diagnostics',len(result_dict.keys),'unchanged inherited methods',len(inherited))
assert len(set(classes))==1
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
